#!/usr/bin/env python3
"""DVI V2 rebuild — general case builder. Expected text is pulled VERBATIM from the
live spec (Rule 113); we only supply structure. Run: python3 build_dvi.py <SECTION>"""
import sys, json, urllib.request, base64
sys.path.insert(0,'/tmp')
from anchor_lib import ANCH, esc

# per-anchor plain-language results (our words), keyed by anchor
PLAIN={}
for _l in open('/tmp/plain_bullets.txt', encoding='utf-8'):
    _l=_l.rstrip('\n')
    if ' ::= ' in _l:
        _k,_v=_l.split(' ::= ',1); PLAIN[_k]=_v

c=json.load(open("/tmp/testrail/creds.json"))
AUTH=base64.b64encode(f"{c['user']}:{c['password']}".encode()).decode()
def post(path,payload):
    req=urllib.request.Request(f"https://shopview.testrail.io/index.php?/api/v2/{path}",
        data=json.dumps(payload).encode(),
        headers={'Authorization':f'Basic {AUTH}','Content-Type':'application/json'},method='POST')
    return json.load(urllib.request.urlopen(req,timeout=60))

SEC={  # section-id + Jira story per S-code
 'S1':(12150,'SV-9099','Require a note on flagged responses'),
 'S17':(12151,'SV-9440','Require a photo on a Not OK response'),
 'S2':(12152,'SV-9100','Turn findings into work order lines'),
 'S3':(12153,'SV-9101','Build from a completed inspection'),
 'S4':(12154,'SV-9102','Build from the inspection note on a work order'),
 'S5':(12155,'SV-9103','Inspection history on the asset record'),
 'S6':(12156,'SV-9104','Build from the asset Inspections tab'),
 'S7':(12157,'SV-9105','Record where the lines came from'),
 'S15':(12158,'SV-9404','Draft the lines with ShopCoach'),
 'S8':(12159,'SV-9106','Record measurements per axle'),
 'S11':(12160,'SV-9109','Attach a reference file to a question'),
 'S12':(12161,'SV-9110','Template builder authoring'),
 'S13':(12162,'SV-9111','Customer-facing inspection report'),
 'S14':(12163,'SV-9397','Inspection filling on a phone'),
 'S18':(12164,'SV-9883','Mark a whole scope OK in one press'),
 'S19':(12165,'SV-10243','Conditional follow-up on a checkbox response'),
}
def block(lines): return "<p>"+"<br>".join(lines)+"</p>"
def expected(scode, anchors, plain=None, atype=2):
    # Layout set by the QA lead 2026-09-22 (Rule 113 amendment):
    # (1) plain results, our words, one per line; (2) Source; (3) exact verbatim quotes.
    secid,story,sname=SEC[scode]
    for a in anchors:
        if a not in PLAIN: raise SystemExit(f"MISSING plain bullet {a}")
    results="".join(f"<li>{esc(PLAIN[a])}</li>" for a in anchors)
    quotes="".join(f"<li><strong>{a}:</strong> &ldquo;{esc(ANCH[a])}&rdquo;</li>" for a in anchors)
    part1=("<p><strong>Expected results</strong></p>"
           f"<ul>{results}</ul>")
    part2=("<p><strong>Source &mdash; where this behaviour comes from</strong><br>"
           f"Epic SV-8181, story {story} ({scode} &mdash; {esc(sname)}); Digital Inspections V2 "
           f"specification, Confluence page 768507905, section {scode}; read on 22 September 2026.</p>")
    part3=("<p><strong>Exact quotes from the source (for reproducibility)</strong></p>"
           f"<ul>{quotes}</ul>")
    marker="<p>AUTOMATION: HOLD - not yet build-verified on the sv8181 QA build</p>"
    return part1+part2+part3+marker

def C(scode,title,pre,steps,anchors,plain=None,atype=2):
    secid=SEC[scode][0]
    for a in anchors:
        if a not in ANCH: raise SystemExit(f"MISSING anchor {a}")
    return (scode,secid,{'title':title,'custom_preconds':block(pre),'custom_steps':block(steps),
            'custom_expected':expected(scode,anchors,plain,atype),
            'custom_automation_type':atype,'custom_atmstatus':1})

