# ---- runner ----
args=sys.argv[1:]
if args and args[0]=='--update':
    # UPDATE mode: rewrite ONLY custom_expected on existing cases (preserve preconds/steps).
    import glob
    from collections import defaultdict
    want=args[1] if len(args)>1 else None
    # section_id -> [created ids in creation order] from every created-*.json
    idlist=defaultdict(list)
    for f in sorted(glob.glob('build/digital-inspections-v2/source-verify-2026-09-22/created-*.json')):
        for e in json.load(open(f)):
            idlist[e['section']].append(e['id'])
    # sanity: cases per section == ids per section
    ncase=defaultdict(int)
    for scode,secid,p in CASES: ncase[secid]+=1
    for secid,n in ncase.items():
        if len(idlist.get(secid,[]))!=n:
            raise SystemExit(f"COUNT MISMATCH sec {secid}: {n} cases vs {len(idlist.get(secid,[]))} ids")
    ptr=defaultdict(int)
    done=[]
    for scode,secid,p in CASES:
        i=ptr[secid]; ptr[secid]+=1
        cid=idlist[secid][i]
        if want and scode!=want: continue
        post(f"update_case/{cid}", {'custom_expected':p['custom_expected']})
        done.append(cid)
        print(f"updated C{cid} <- {scode} #{i} | {p['title'][:55]}")
    print("updated",len(done),"cases")
else:
    want=args[0] if args else None
    created=[]
    for scode,secid,p in CASES:
        if want and scode!=want: continue
        r=post(f"add_case/{secid}",p)
        created.append({'id':r['id'],'section':secid,'scode':scode,'title':p['title']})
        print(f"C{r['id']} <- {secid} ({scode}) | {p['title']}")
    if created:
        path=f"build/digital-inspections-v2/source-verify-2026-09-22/created-{want or 'ALL'}.json"
        json.dump(created,open(path,'w'),indent=2)
        print("wrote",path,"| ids:",[x['id'] for x in created])
    else:
        print("no cases matched",want)
